func permute(nums []int) [][]int {
    var res [][]int
    n := len(nums)
    path := make([]int, 0, n)
    used := make([]bool, n)
    var backtrack func()
    backtrack = func() {
        if len(path) == n {
            res = append(res, append([]int{}, path...))
            return
        }
        for i := 0; i < n; i++ {
            if used[i] {
                continue
            }
            used[i] = true
            path = append(path, nums[i])
            backtrack()
            path = path[:len(path)-1]
            used[i] = false
        }
    }
    backtrack()
    return res
}

func permute(nums []int) [][]int {
    var res [][]int
    var backtrack func(int)
    backtrack = func(start int) {
        if start == len(nums) {
            res = append(res, append([]int{}, nums...))
            return
        }
        for i := start; i < len(nums); i++ {
            nums[start], nums[i] = nums[i], nums[start]
            backtrack(start + 1)
            nums[start], nums[i] = nums[i], nums[start]
        }
    }
    backtrack(0)
    return res
}
